from collections import defaultdict
from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # employee -> year -> days used
        self._used_days: dict[str, dict[int, int]] = defaultdict(lambda: defaultdict(int))

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if start > end:
            raise ValueError("Start date must be on or before end date.")

        if (start - today).days < 3:
            raise ValueError("Requests must be made at least 3 days before the start date.")

        # Count requested leave days partitioned by calendar year
        requested_by_year: dict[int, int] = defaultdict(int)
        current = start
        while current <= end:
            # Monday is 0, Sunday is 6; weekends are 5 and 6
            if current.weekday() < 5 and current not in self.holidays:
                requested_by_year[current.year] += 1
            current += timedelta(days=1)

        # Validate that each year touched has sufficient remaining days
        for year, needed_days in requested_by_year.items():
            if needed_days > self.remaining(employee, year):
                raise ValueError(
                    f"Employee '{employee}' does not have enough remaining leave days for year {year}."
                )

        # Deduct the days
        total_days = 0
        for year, needed_days in requested_by_year.items():
            self._used_days[employee][year] += needed_days
            total_days += needed_days

        return total_days

    def remaining(self, employee: str, year: int) -> int:
        return self.days_per_year - self._used_days[employee][year]
```

